def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def containsSubtree(tree, sub):
    if not sub:
        return True
    table = {}

    def ids(t):
        vals, left, right = _links(t)
        out = [0] * len(vals)
        for k in range(len(vals) - 1, -1, -1):
            lid = out[left[k]] if left[k] != -1 else 0
            rid = out[right[k]] if right[k] != -1 else 0
            out[k] = table.setdefault((vals[k], lid, rid), len(table) + 1)
        return out

    a = ids(tree)
    b = ids(sub)
    return b[0] in set(a)
